const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../cron_day.cjs');
test('restricted day fields and Sunday alias', () => {
 const rows=[['13','5',13,2,true],['13','5',12,5,true],['13','5',12,2,false],['*','5',13,2,false],['*','5',13,5,true],['13','*',12,5,false],['13','*',13,2,true],['*','*',4,3,true],['*','7',4,0,true],['13','0',4,0,true],['13','7',4,0,true]];
 for(const [dom,dow,d,w,want] of rows) assert.equal(app.matchesDay(dom,dow,d,w),want);
});

test('both restricted fields may match together', () => {
  assert.equal(app.matchesDay('13','5',13,5),true);
  assert.equal(app.matchesDay('13','7',13,0),true);
  assert.equal(app.matchesDay('13','7',12,1),false);
});

