function matchesDay(dom, dow, day, weekday) {
  const dm = dom === '*' || Number(dom) === day;
  const wm = dow === '*' || Number(dow) % 7 === weekday % 7;
  if (dom === '*') return wm;
  if (dow === '*') return dm;
  return dm || wm;
}
module.exports = { matchesDay };
